ORGO.reg({"types":{},"items":{"exam-q3a-traits":{"id":"exam-q3a-traits","type":"traits","role":"exam","kind":"multi","diff":2,"src":"FA24 Exam 2, Q3A","fixed":true,"stem":"Which of the following are <b>NOT</b> characteristics of {{SN1}} reactions? Circle all that apply.","choices":[{"h":"The electrophilic carbon undergoes inversion of stereochemistry","ok":true,"why":"Not SN1. The carbocation is planar and the nucleophile can approach either face, so SN1 gives a racemic mixture. Inversion belongs to SN2."},{"h":"The rate is proportional to the concentration of substrate (electrophile)","ok":false,"why":"This one is true of SN1, so it must not be circled: rate = k[substrate]. Circling it means the NOT in the question was missed."},{"h":"The rate is proportional to the concentration of nucleophile","ok":true,"why":"Not SN1. The nucleophile arrives after the rate-determining step, so its concentration is not in the rate law. In the lecture's data, doubling [{{H2O}}] left the rate unchanged."},{"h":"The rate is independent of the solvent","ok":true,"why":"Not SN1. Increasing the polarity of the solvent increases the rate: a polar protic solvent stabilizes the transition state of the ionization."}],"solution":{"steps":[{"t":"Write down what SN1 is","h":"The lecture's summary: stable carbocation, poor nucleophile, favored by polar protic solvents, racemization. Rate = k[substrate]: unimolecular."},{"t":"Test each statement","h":"A, inversion: false for SN1 (that is SN2). B, rate depends on substrate: true. C, rate depends on nucleophile: false. D, rate independent of solvent: false."},{"t":"Mind the NOT","h":"The question asks for the statements that do not describe SN1. Circle the three false ones and leave B alone."}],"answer":"A, C and D","rule":"SN1: rate = k[substrate] only, racemization, faster in more polar protic solvents."}},"traits-s01":{"id":"traits-s01","type":"traits","kind":"multi","diff":2,"src":"FA24 Exam 2, Q3A","fixed":true,"stem":"Which of the following is <b>NOT</b> a characteristic of {{SN1}} reactions? Circle all that apply.","choices":[{"h":"The electrophilic carbon undergoes inversion of stereochemistry","ok":true,"why":"Not SN1: a planar carbocation is attacked on either face, which gives a racemic mixture. Inversion belongs to SN2.","err":"SN1-02"},{"h":"The rate is proportional to the concentration of substrate (electrophile)","ok":false,"why":"This is true of SN1: rate = k[substrate]. The slow step is the ionization of the substrate alone."},{"h":"The rate is proportional to the concentration of nucleophile","ok":true,"why":"Not SN1: the nucleophile arrives after the rate-determining step, so its concentration does not appear in the rate law."},{"h":"The rate is independent of the solvent","ok":true,"why":"Not SN1: a more polar, protic solvent stabilizes the transition state for ionization and speeds the reaction."}],"solution":{"steps":[{"t":"Recall the four facts","h":"SN1: stable carbocation, poor nucleophile, polar protic solvent, racemization. Rate = k[substrate]."},{"t":"Test each statement","h":"Inversion: false (SN2). Rate depends on substrate: true. Rate depends on nucleophile: false. Independent of solvent: false."},{"t":"Mind the NOT","h":"The question asks for the statements that are not characteristics, so circle the three false ones."}],"answer":"A, C and D","rule":"SN1: rate = k[substrate], racemization, faster in polar protic solvents."},"role":"practice"}},"mols":{}});
